<?php
namespace Tests\Feature\Documents;
use App\Domain\Documents\Enums\DocumentStatus;use App\Domain\Storage\Services\SecurePdfIngestor;use App\Models\{District,Document,DocumentCategory,DocumentType,RevenueCircle,State,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\Storage;use Tests\TestCase;
class SecurePdfIngestorTest extends TestCase{use RefreshDatabase;public function test_valid_pdf_becomes_checksum_verified_master():void{$this->seed();Storage::fake('local');$u=User::factory()->create();$s=State::where('code','AS')->firstOrFail();$d=District::create(['ulid'=>(string)\Illuminate\Support\Str::ulid(),'state_id'=>$s->id,'code'=>'TST','name_en'=>'Test District']);$c=RevenueCircle::create(['ulid'=>(string)\Illuminate\Support\Str::ulid(),'district_id'=>$d->id,'code'=>'C1','name_en'=>'Circle']);$cat=DocumentCategory::create(['code'=>'TEST','name_en'=>'Test']);$type=DocumentType::create(['document_category_id'=>$cat->id,'code'=>'TEST_DOC','name_en'=>'Test']);$doc=Document::create(['reference_no'=>'AS-LR-2026-0000009999','document_category_id'=>$cat->id,'document_type_id'=>$type->id,'state_id'=>$s->id,'district_id'=>$d->id,'revenue_circle_id'=>$c->id,'title'=>'Test','status'=>DocumentStatus::AwaitingUpload,'registered_by'=>$u->id,'registered_at'=>now()]);$tmp=tempnam(sys_get_temp_dir(),'pdf');file_put_contents($tmp,"%PDF-1.4\n1 0 obj\n<<>>\nendobj\n%%EOF\n");$upload=new UploadedFile($tmp,'scan.pdf','application/pdf',null,true);$file=app(SecurePdfIngestor::class)->ingest($doc,$upload,$u->id);$this->assertSame('MASTER',$file->file_role);$this->assertSame(64,strlen($file->sha256));$this->assertSame('PROCESSING',$doc->fresh()->status->value);}}
